## Secure Implementation

### Tier 1: Critical Fix (5 min)

**Never evaluate user input as SpEL - use predefined expressions**

```java
// SECURE: Predefined filter expressions with whitelist
package com.example.search;

import org.springframework.web.bind.annotation.*;
import java.util.List;
import java.util.Map;
import java.util.function.Predicate;

@RestController
@RequestMapping("/api/search")
public class SecureSearchController {

    // ✅ SECURE: Whitelist of allowed filter operations
    private static final Map<String, Predicate<Product>> ALLOWED_FILTERS = Map.of(
        "price_gt_100", p -> p.getPrice() > 100,
        "price_lt_50", p -> p.getPrice() < 50,
        "in_stock", p -> p.getStock() > 0,
        "on_sale", p -> p.isOnSale()
    );

    @GetMapping("/filter")
    public List<Product> searchProducts(@RequestParam String filterName) {

        // ✅ SECURE: User input used as dictionary key, not evaluated
        Predicate<Product> filter = ALLOWED_FILTERS.get(filterName);

        if (filter == null) {
            throw new IllegalArgumentException("Invalid filter: " + filterName);
        }

        return productRepository.findAll().stream()
            .filter(filter)
            .collect(Collectors.toList());
    }
}
```

### Tier 2: Essential Defenses (15 min)

**Sandboxed SpEL evaluation if absolutely required**

```java
// SECURE: Sandboxed SpEL with restricted evaluation context
package com.example.search;

import org.springframework.expression.*;
import org.springframework.expression.spel.standard.SpelExpressionParser;
import org.springframework.expression.spel.support.SimpleEvaluationContext;
import org.springframework.stereotype.Service;
import java.util.Set;

@Service
public class SecureSpelEvaluator {

    private final ExpressionParser parser = new SpelExpressionParser();

    // ✅ SECURE: Whitelist of allowed properties
    private static final Set<String> ALLOWED_PROPERTIES = Set.of(
        "price", "name", "stock", "category"
    );

    // ✅ SECURE: Whitelist of allowed operators
    private static final Set<String> ALLOWED_OPERATORS = Set.of(
        ">", "<", "==", "!=", ">=", "<=", "and", "or"
    );

    public boolean evaluateSafe(String expression, Product product) {
        // ✅ Input validation before evaluation
        if (!isExpressionSafe(expression)) {
            throw new SecurityException("Unsafe expression detected: " + expression);
        }

        // ✅ Use SimpleEvaluationContext (no class loading, no bean references)
        EvaluationContext context = SimpleEvaluationContext
            .forReadOnlyDataBinding()
            .withRootObject(product)
            .build();

        try {
            Expression exp = parser.parseExpression(expression);
            return Boolean.TRUE.equals(exp.getValue(context, Boolean.class));
        } catch (Exception e) {
            throw new SecurityException("Expression evaluation failed", e);
        }
    }

    // ✅ Strict input validation
    private boolean isExpressionSafe(String expression) {
        // Block T() operator (class instantiation)
        if (expression.contains("T(")) {
            return false;
        }

        // Block dangerous method calls
        String[] dangerousPatterns = {
            "Runtime", "exec", "ProcessBuilder", "getClass",
            "forName", "newInstance", "invoke", "getMethod",
            "System", "getenv", "getProperty", "Files", "Paths"
        };

        for (String pattern : dangerousPatterns) {
            if (expression.contains(pattern)) {
                return false;
            }
        }

        return true;
    }
}

