### Tier 3: Production Hardening (30 min)

**Add monitoring, testing, and runtime protection**

```java
// SECURE: SpEL injection detection
package com.example.security;

import io.micrometer.core.instrument.Counter;
import io.micrometer.core.instrument.MeterRegistry;
import org.springframework.stereotype.Component;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;

@Component
public class SpelSecurityMonitor {

    private static final Logger log = LoggerFactory.getLogger(SpelSecurityMonitor.class);
    private final Counter spelInjectionAttempts;
    private final Counter dangerousExpressions;

    public SpelSecurityMonitor(MeterRegistry registry) {
        this.spelInjectionAttempts = Counter.builder("spel.injection.attempts")
            .description("SpEL injection attempts detected")
            .tag("severity", "critical")
            .register(registry);

        this.dangerousExpressions = Counter.builder("spel.dangerous.expressions")
            .description("Dangerous SpEL expressions blocked")
            .register(registry);
    }

    public void recordInjectionAttempt(String expression, String remoteIp) {
        log.warn("SpEL injection attempt from {}: {}", remoteIp, expression);
        spelInjectionAttempts.increment();
    }

    public void recordDangerousExpression(String expression) {
        log.error("Dangerous SpEL expression blocked: {}", expression);
        dangerousExpressions.increment();
    }
}

